grep -n "CONF_SLOT\|slot_num" custom_components/lock_code_manager/config_flow.py | head -30 && echo "=== strings: allocation errors ===" && python3 -c "
import json,sys
d=json.load(open('custom_components/lock_code_manager/strings.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'/'+k)
    elif isinstance(o,str) and ('occupancy_unknown' in p or 'search_limit' in p or 'exceed_capacity' in p):
        print(p,'=>',o)
walk(d)"

